// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        // fund the contract directly so the owner has something to withdraw
        vm.deal(address(c), amount);

        uint256 ownerBefore = address(this).balance;
        vm.prank(address(this)); // owner is the deployer (this test contract)
        c.withdraw(amount);
        uint256 ownerAfter = address(this).balance;

        // Rule: withdraw(v) by the owner credits the owner with exactly v.
        assertTrue(ownerAfter - ownerBefore == amount);
    }

    // allow this contract to receive the transferred ether
    receive() external payable {}
}
